*{box-sizing:border-box} :root{--ink:#24372c;--soft:#667969;--cream:#fffaf0;--gold:#e5b866;--glass:rgba(255,251,242,.91)} html,body,#game-shell{margin:0;width:100%;height:100%;overflow:hidden}body{font-family:'DM Sans',sans-serif;color:var(--ink);background:#dce7d4}#game-shell{position:relative;isolation:isolate}#scene{position:absolute;inset:0;width:100%;height:100%;display:block;touch-action:none}.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(24,43,33,.2),transparent 22%,transparent 72%,rgba(24,43,33,.26));z-index:1}.topbar{position:absolute;z-index:3;inset:0 0 auto;display:flex;align-items:center;justify-content:space-between;padding:20px 34px;color:#fff}.brand{display:flex;align-items:center;gap:10px;text-decoration:none;color:#fff;font-size:9px;letter-spacing:2px;line-height:1.25;text-shadow:0 1px 5px #354a33}.brand b{font-size:14px;letter-spacing:3.3px}.brand-mark{font-size:25px;color:#f6d79a}.location-pill{position:absolute;left:50%;transform:translateX(-50%);background:rgba(35,52,40,.35);border:1px solid rgba(255,255,255,.25);backdrop-filter:blur(12px);border-radius:30px;padding:10px 16px;display:flex;align-items:center;gap:9px;font-size:12px;letter-spacing:.2px;white-space:nowrap}.location-dot{width:7px;height:7px;border-radius:50%;background:#c9e69d;box-shadow:0 0 10px #d5f9a2}.weather{border-left:1px solid rgba(255,255,255,.3);padding-left:12px;color:#ffdfa2}.weather span{color:#fff}.icon-button{width:42px;height:42px;border-radius:50%;border:1px solid rgba(255,255,255,.4);background:rgba(36,55,44,.3);color:white;font-size:24px;backdrop-filter:blur(9px);cursor:pointer}.intro-card{position:absolute;z-index:2;left:8.1%;top:50%;transform:translateY(-42%);width:min(410px,38vw);padding:34px 36px;background:var(--glass);border-radius:5px 24px 24px 24px;box-shadow:0 20px 60px #253c2b26;transition:opacity .5s,transform .5s}.intro-card.closed{opacity:0;transform:translate(-20px,-42%);pointer-events:none}.eyebrow{font-size:10px;letter-spacing:2.4px;font-weight:700;color:#788b6e;text-transform:uppercase}.intro-card h1,.modal-panel h2{font-family:Fraunces,Georgia,serif;font-size:44px;line-height:1.08;letter-spacing:-1.6px;font-weight:500;margin:13px 0 14px}.intro-card h1 i,.modal-panel h2 i{font-weight:500;color:#728b5b}.intro-card p,.modal-panel>p{font-size:14px;line-height:1.75;color:#657466;margin:0 0 23px}.primary-button{background:#526e49;color:#fff;border:0;border-radius:7px;padding:14px 18px;font:600 13px 'DM Sans',sans-serif;letter-spacing:.2px;cursor:pointer;box-shadow:0 6px 16px #48644130;transition:transform .2s,background .2s}.primary-button:hover{background:#415b3b;transform:translateY(-2px)}.primary-button span{font-size:17px;margin-left:20px}.intro-note{font-size:10px;color:#84907f;margin-top:18px}.intro-note span{color:#d8aa58;margin-right:5px}.quest-card{position:absolute;top:97px;left:34px;width:210px;padding:15px 16px 13px;background:rgba(255,252,242,.9);border-radius:4px 15px 15px 15px;box-shadow:0 8px 26px #2c403322;z-index:2}.quest-label{font-size:8px;letter-spacing:1.7px;font-weight:700;color:#829177}.quest-label span{float:right;color:#d4a84e}.quest-title{font:500 16px Fraunces,Georgia,serif;margin:8px 0 12px}.quest-progress{height:3px;background:#e2e7dc;border-radius:3px}.quest-progress span{display:block;width:25%;height:100%;background:#d0aa61;border-radius:3px;transition:width .4s}.quest-foot{display:flex;justify-content:space-between;font-size:9px;color:#869082;margin-top:7px}.side-actions{position:absolute;right:27px;top:87px;z-index:2;display:flex;gap:10px}.round-button{display:grid;place-items:center;gap:3px;width:58px;height:58px;border:1px solid #fff9;border-radius:50%;background:#253a2b69;color:white;backdrop-filter:blur(8px);cursor:pointer}.round-button span{font-size:20px}.round-button small{font-size:9px}.bottom-ui{position:absolute;z-index:3;bottom:24px;left:30px;right:30px;display:flex;align-items:center;justify-content:space-between;gap:15px}.player-chip{display:flex;align-items:center;gap:10px;color:#fff;min-width:195px;text-shadow:0 1px 4px #203525}.player-avatar{width:42px;height:42px;display:grid;place-items:center;border:1px solid #fff8;border-radius:50%;background:#f8e9c2;font-size:22px;text-shadow:none}.player-chip b{font-size:12px;display:block}.player-chip small{font-size:9px;opacity:.82}.level-badge{margin-left:7px;font-size:10px;color:#ffe2a6}.territory-tabs{display:flex;gap:6px;padding:5px;border:1px solid #fff5;border-radius:30px;background:#263a2d4d;backdrop-filter:blur(10px)}.territory-tab{border:0;background:transparent;color:#fff;padding:9px 14px;border-radius:25px;font:500 11px 'DM Sans',sans-serif;cursor:pointer;white-space:nowrap;transition:.2s}.territory-tab.active{background:#fff2d6;color:#41583d}.map-button{border:1px solid #fff9;border-radius:25px;background:#263a2d55;color:white;padding:11px 16px;font:500 11px 'DM Sans',sans-serif;cursor:pointer;backdrop-filter:blur(8px);min-width:130px}.map-button span{font-size:16px;margin-right:5px}.controls-hint{position:absolute;bottom:91px;left:50%;transform:translateX(-50%);z-index:2;color:#ffffffda;font-size:10px;text-shadow:0 1px 4px #263529;white-space:nowrap}.controls-hint span{padding:4px 7px;border-radius:4px;background:#fff3;font-size:9px;font-weight:700}.controls-hint i{padding:0 7px;color:#ffdda0;font-style:normal}.nearby-hint{position:absolute;z-index:4;bottom:105px;left:50%;transform:translateX(-50%);background:#fffaf0e8;padding:10px 15px;border-radius:30px;font-size:11px;box-shadow:0 5px 20px #1c332833;white-space:nowrap}.nearby-hint>span{color:#c79b4b;margin-right:5px}.nearby-hint kbd{font:700 9px 'DM Sans';margin-left:10px;padding:4px 6px;background:#e8ebdf;border-radius:4px}.mobile-controls{position:absolute;z-index:4;bottom:90px;left:22px;right:22px;align-items:end;justify-content:space-between;pointer-events:none}.joystick{width:112px;height:112px;border-radius:50%;background:#273c2c3b;border:1px solid #ffffff75;backdrop-filter:blur(5px);pointer-events:auto;touch-action:none;position:relative}.stick{position:absolute;width:48px;height:48px;border-radius:50%;background:#fff9;border:1px solid #fff;left:31px;top:31px;box-shadow:0 3px 8px #1d332c30}.interact-button{width:67px;height:67px;border:1px solid #fff9;border-radius:50%;background:#546f4ce8;color:#fff;font-size:24px;pointer-events:auto;box-shadow:0 5px 18px #253e3270}.interact-button small{display:block;font:10px 'DM Sans';margin-top:0}.toast{position:absolute;z-index:8;left:50%;top:80px;transform:translate(-50%,-10px);background:#fffaf0;color:#435640;padding:11px 18px;border-radius:25px;box-shadow:0 5px 24px #273c2d33;font-size:12px;opacity:0;pointer-events:none;transition:.25s}.toast.show{opacity:1;transform:translate(-50%,0)}.modal-backdrop{position:absolute;inset:0;background:#1f352987;backdrop-filter:blur(7px);z-index:10;display:grid;place-items:center;padding:20px}.modal-panel{position:relative;width:min(560px,100%);max-height:90vh;overflow:auto;background:#fffaf0;border-radius:8px 26px 26px;padding:37px 40px;box-shadow:0 24px 80px #14271a66;animation:modalIn .28s ease-out}@keyframes modalIn{from{transform:translateY(12px);opacity:0}to{transform:none;opacity:1}}.modal-panel h2{font-size:37px;margin:10px 0 12px}.modal-panel>p{font-size:12px;max-width:420px}.close-button{position:absolute;right:18px;top:16px;border:0;background:#e9eddf;color:#667962;border-radius:50%;width:32px;height:32px;font-size:22px;cursor:pointer;line-height:1}.territory-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:20px}.territory-card{border:1px solid #e1e6d9;border-radius:12px;padding:14px;text-align:left;background:#fffdf7;cursor:pointer;transition:.2s;position:relative;overflow:hidden}.territory-card:hover{border-color:#9caf88;transform:translateY(-2px);box-shadow:0 6px 14px #415b3b1a}.territory-card.active{background:#eef3e7;border-color:#aabf94}.territory-card .emoji{font-size:22px}.territory-card b{display:block;font:500 16px Fraunces,Georgia,serif;margin:6px 0 3px}.territory-card small{display:block;color:#7b8778;font-size:10px;line-height:1.45}.territory-card .cat-count{position:absolute;right:12px;top:15px;font-size:9px;color:#87967b}.modal-footnote{font-size:10px;color:#99a18f;margin-top:18px;text-align:center}.journal-stats{display:flex;gap:30px;padding:15px 0 19px;border-bottom:1px solid #e4e6dc}.journal-stats b{display:block;font:500 25px Fraunces,Georgia,serif;color:#58714d}.journal-stats small{font-size:9px;color:#899184}.journal-entry{display:flex;gap:13px;padding:16px 0;border-bottom:1px solid #e9e9df}.entry-icon{font-size:21px}.journal-entry b{font:500 15px Fraunces,Georgia,serif}.journal-entry p{margin:4px 0 0;color:#7b8778;font-size:11px;line-height:1.6}.dialogue-panel{text-align:center;width:min(430px,100%);padding:40px}.dialog-cat{font-size:51px;width:82px;height:82px;margin:0 auto 15px;display:grid;place-items:center;border-radius:50%;background:#e9efdf}.dialogue-panel .eyebrow{font-size:9px}.dialogue-panel h2{margin:7px 0;font-size:34px}.dialogue-panel .cat-details{margin:0 auto 18px}.dialogue-panel blockquote{margin:0 0 22px;padding:14px 18px;border-left:2px solid #d6b66f;background:#f4f2e7;text-align:left;font:italic 14px/1.6 Fraunces,Georgia,serif;color:#64735d;border-radius:0 8px 8px 0}.dialog-next{min-width:150px}.loading-screen{position:absolute;z-index:20;inset:0;background:#dce8d4;display:flex;align-items:center;justify-content:center;flex-direction:column;color:#52684c;font:500 13px Fraunces,Georgia,serif;transition:opacity .6s}.loading-screen.done{opacity:0;pointer-events:none}.loading-mark{font-size:42px;color:#89a376;margin-bottom:8px;animation:bloom 2s infinite ease-in-out}@keyframes bloom{50%{transform:rotate(45deg) scale(1.13)}}.loading-bar{margin-top:15px;width:115px;height:3px;border-radius:3px;background:#bdcbb4;overflow:hidden}.loading-bar span{display:block;width:40%;height:100%;background:#748f64;animation:load 1.3s infinite ease-in-out}@keyframes load{from{transform:translateX(-110%)}to{transform:translateX(300%)}}[hidden]{display:none!important}
@media(max-width:700px){.topbar{padding:14px 16px}.brand{font-size:7px}.brand b{font-size:11px}.brand-mark{font-size:21px}.location-pill{top:66px;left:50%;font-size:10px;padding:8px 11px}.weather{padding-left:8px}.map-toggle{width:38px;height:38px}.intro-card{left:18px;right:18px;top:37%;transform:translateY(-20%);width:auto;padding:26px 24px;border-radius:4px 20px 20px}.intro-card.closed{transform:translateY(-10px)}.intro-card h1{font-size:36px}.intro-card p{font-size:12px;margin-bottom:18px}.quest-card{top:108px;left:14px;width:178px;padding:12px}.quest-title{font-size:14px}.side-actions{top:109px;right:13px;gap:5px}.round-button{width:45px;height:45px}.round-button span{font-size:17px}.round-button small{font-size:8px}.bottom-ui{bottom:15px;left:13px;right:13px;display:grid;grid-template-columns:1fr auto;gap:9px}.player-chip{min-width:0}.player-avatar{width:36px;height:36px;font-size:18px}.player-chip b{font-size:10px}.player-chip small{font-size:8px}.territory-tabs{grid-column:1/3;grid-row:2;justify-content:space-between;width:100%;gap:0;padding:3px}.territory-tab{font-size:9px;padding:8px 9px}.map-button{min-width:0;padding:9px 11px;font-size:10px}.controls-hint{display:none!important}.mobile-controls{display:flex!important;bottom:96px;left:17px;right:17px}.joystick{width:92px;height:92px}.stick{width:42px;height:42px;left:24px;top:24px}.interact-button{width:59px;height:59px}.nearby-hint{bottom:204px;font-size:10px}.quest-card~.bottom-ui{bottom:12px}.modal-panel{padding:30px 24px;border-radius:5px 22px 22px;max-height:88vh}.modal-panel h2{font-size:32px}.territory-grid{gap:7px}.territory-card{padding:11px}.territory-card b{font-size:14px}.territory-card small{font-size:9px}.journal-stats{gap:19px}.dialogue-panel{padding:34px 25px}.toast{top:108px;font-size:11px}.vignette{background:linear-gradient(180deg,rgba(24,43,33,.22),transparent 18%,transparent 58%,rgba(24,43,33,.36))}}
@media(min-width:701px) and (max-height:600px){.intro-card{top:52%;padding:22px 28px}.intro-card h1{font-size:36px}.intro-card p{margin-bottom:13px}.bottom-ui{bottom:12px}.controls-hint{bottom:72px}}

import * as THREE from 'three';

const $=s=>document.querySelector(s), canvas=$('#scene');
const clans=[
 {id:'thunder',name:'ThunderClan',place:'Forest Clearing',icon:'🌳',color:'#73915e',sky:0xb7d2b2,ground:0x829769,accent:'#9ab57a',desc:'An old forest of oak, fern, and dappled sun.', cats:[['Mossstar','Leader','adult','A silver tabby with a calm, watchful gaze.','“A kind heart is a strength, little one. Never let anyone tell you otherwise.”','🐈‍⬛'],['Brambleclaw','Deputy','adult','Broad-shouldered and weathered, but warm-eyed.','“The best patrols are the ones where nothing happens. Still, keep your ears open!”','🐈'],['Cinderpelt','Medicine cat','adult','A gentle tortoiseshell among fragrant herbs.','“These leaves will soothe a scratch. Remember: patience is the first medicine.”','🐈‍⬛'],['Dapplepaw','Apprentice','young','A lively ginger kit practicing a very serious pounce.','“I saw a butterfly as big as a leaf! Well… maybe a little smaller.”','🐈'],['Elder Fern','Elder','elder','A fluffy old brown cat resting in a patch of sun.','“In my day, the rabbits were twice as plump. Or perhaps I was just smaller.”','🐈'],['Hazelstripe','Warrior · patrol','adult','A russet warrior keeping a quiet watch on the trail.','“All clear along the bramble path. The birds are singing today.”','🐈‍⬛']], patrol:'Bramble Path'},
 {id:'shadow',name:'ShadowClan',place:'Pine Hollow',icon:'🌲',color:'#71876b',sky:0xa9b8a8,ground:0x687a61,accent:'#9caf79',desc:'A secretive pinewood of mossy pools and ferny shade.', cats:[['Nightstar','Leader','adult','A sleek black cat, composed as a shadow.','“There is wisdom in quiet places. Listen before you leap.”','🐈‍⬛'],['Pinewhisker','Deputy','adult','A dark brown tabby with a keen nose.','“The pine needles soften every footstep. Makes for a fine patrol.”','🐈'],['Mothwing','Medicine cat','adult','A pale golden cat arranging herbs in neat piles.','“This one is for a cough. That one is for a sore paw. Herbs have their own stories.”','🐈'],['Mudpaw','Apprentice','young','A small black kit with mud on both paws.','“I found a frog! It found me too, I think.”','🐈‍⬛'],['Old Yew','Elder','elder','A silver-flecked elder curled beside a root.','“The moon is brighter here. Or perhaps the pines make it seem so.”','🐈'],['Shadefoot','Warrior · patrol','adult','A lithe charcoal warrior scanning the undergrowth.','“No strange scents on the border. Just rain and wild mint.”','🐈‍⬛']], patrol:'The Pine Needles'},
 {id:'river',name:'RiverClan',place:'Silverstream Bend',icon:'💧',color:'#6e9a9b',sky:0xb4d5d6,ground:0x879a7f,accent:'#8fc0bd',desc:'A willow-fringed stream where minnows flash like stars.', cats:[['Ripplestar','Leader','adult','A sleek blue-grey cat with bright, clear eyes.','“The river teaches us to bend, little fern, but never to break.”','🐈‍⬛'],['Reedtail','Deputy','adult','A spotted cat with river-reed whiskers.','“There are silver minnows near the bend. Best fishing in moons!”','🐈'],['Willowshine','Medicine cat','adult','A cream cat with a small bundle of waterside herbs.','“The willow bark helps with aches. The river gives us so much.”','🐈'],['Minnowpaw','Apprentice','young','A white kitten watching ripples with great intensity.','“I almost caught one! It was very slippery and also very fast.”','🐈'],['Pebblepelt','Elder','elder','A round, drowsy elder with a blue-grey coat.','“I used to swim across that river in one breath. Used to.”','🐈‍⬛'],['Otterstep','Warrior · patrol','adult','A confident brown warrior padding along the bank.','“The water is calm today. Good weather for a border walk.”','🐈']], patrol:'The Willow Bank'},
 {id:'wind',name:'WindClan',place:'Breezekit Downs',icon:'🌾',color:'#b09b69',sky:0xc9d8bd,ground:0xa6a471,accent:'#d7bd75',desc:'Open highland hills where heather waves in the wind.', cats:[['Cloudstar','Leader','adult','A white cat whose fur ruffles in the open breeze.','“Out here, the sky belongs to everyone. Take a moment and look up.”','🐈'],['Hareleap','Deputy','adult','A long-legged pale ginger cat, quick as the wind.','“The moor is full of fresh tracks. Want to race me to the hill?”','🐈'],['Thymeleaf','Medicine cat','adult','A soft grey cat with a sprig of thyme tucked behind one ear.','“The air smells sweet today. Thyme and heather, mostly.”','🐈‍⬛'],['Bunnyhop','Apprentice','young','A pale kitten bouncing after a drifting seed.','“I can jump over that rock! Watch! …Maybe after lunch.”','🐈'],['Whitetail','Elder','elder','A fluffy elder nestled in a sun-warmed dip.','“The stars feel close on a clear moor night.”','🐈‍⬛'],['Swiftstep','Warrior · patrol','adult','A sleek brown warrior trotting the open perimeter.','“The border is quiet. I can see for miles from the ridge.”','🐈']], patrol:'The Heather Ridge'}
];
let active=0,started=false,greetings=0,visits=new Set([0]),secrets=0,lastGreeting='',muted=false;
let scene,camera,renderer,clock,world,player,playerModel,playerTail,activeCats=[],keys={},nearby=null;
let yaw=0.25,pitch=.24,dragging=false,prev={x:0,y:0},joystick={x:0,y:0},touchId=null;
const catPalette=[0xc99465,0x737b70,0xe6d6ad,0x5b5751,0xa77b5d,0xc0ad8e];
function init(){scene=new THREE.Scene();scene.background=new THREE.Color(clans[0].sky);scene.fog=new THREE.Fog(clans[0].sky,24,76);camera=new THREE.PerspectiveCamera(54,innerWidth/innerHeight,.1,140);renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false});renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.08;clock=new THREE.Clock();scene.add(new THREE.HemisphereLight(0xe4f0d7,0x5a6246,2.1));let sun=new THREE.DirectionalLight(0xffe6b5,2.2);sun.position.set(-15,25,11);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);sun.shadow.camera.left=-28;sun.shadow.camera.right=28;sun.shadow.camera.top=28;sun.shadow.camera.bottom=-28;sun.shadow.bias=-.0003;scene.add(sun);world=new THREE.Group();scene.add(world);buildPlayer();buildTerritory(0);setupUI();resize();renderer.setAnimationLoop(tick);setTimeout(()=>$('#loading-screen').classList.add('done'),650);}
function mat(color,rough=1){return new THREE.MeshStandardMaterial({color,roughness:rough});}
function mesh(geo,material,parent,x=0,y=0,z=0){let m=new THREE.Mesh(geo,material);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m;}
function sphere(parent,color,pos,scale,geo){let m=mesh(geo||new THREE.SphereGeometry(1,12,9),mat(color),parent,...pos);m.scale.set(...scale);return m;}
function makeCat(colors={}){let g=new THREE.Group();let fur=mat(colors.fur??0xc99465),cream=mat(colors.cream??0xe7d2ae),dark=mat(colors.dark??0x59483c),eye=mat(0x697b55,.35);const body=mesh(new THREE.SphereGeometry(.48,16,12),fur,g,0,.62,0);body.scale.set(.74,.59,1.13);let chest=mesh(new THREE.SphereGeometry(.31,12,10),cream,g,0,.56,-.39);chest.scale.set(.7,.82,.62);let head=new THREE.Group();g.add(head);head.position.set(0,.98,-.53);let skull=mesh(new THREE.SphereGeometry(.34,16,12),fur,head);skull.scale.set(1,.83,.88);for(let s of [-1,1]){let ear=mesh(new THREE.ConeGeometry(.115,.3,4),fur,head,s*.22,.28,-.015);ear.rotation.z=-s*.18;let inner=mesh(new THREE.ConeGeometry(.066,.2,4),mat(0xd99386),head,s*.22,.27,-.015);inner.rotation.z=-s*.18;sphere(head,0xf5ebca,[s*.125,.035,-.285],[.055,.065,.04]);sphere(head,0x566648,[s*.125,.035,-.322],[.026,.041,.016]);}sphere(head,0x8b6254,[0,-.055,-.333],[.047,.031,.023]);for(let s of [-1,1]){let whisk=new THREE.Mesh(new THREE.CylinderGeometry(.004,.004,.24,4),mat(0xf4ead8));whisk.position.set(s*.2,-.08,-.28);whisk.rotation.z=s*.25;head.add(whisk)}let legs=[];for(let s of [-1,1])for(let z of [-.3,.32]){let leg=mesh(new THREE.CylinderGeometry(.095,.075,.43,8),fur,g,s*.23,.3,z);leg.rotation.x=z*.12;let paw=mesh(new THREE.SphereGeometry(.12,9,7),fur,g,s*.23,.1,z-.02);paw.scale.set(1,.55,1.2);legs.push({leg,paw,phase:(s+z)*1.5});}let tail=new THREE.Group();tail.position.set(0,.78,.42);g.add(tail);let t1=mesh(new THREE.CylinderGeometry(.095,.13,.43,9),fur,tail,0,.18,.18);t1.rotation.x=-.8;let t2=mesh(new THREE.CylinderGeometry(.065,.095,.34,9),fur,tail,0,.46,.39);t2.rotation.x=-1.05;let t3=mesh(new THREE.SphereGeometry(.09,9,7),fur,tail,0,.59,.51);g.userData={head,legs,tail,body};return g;}
function buildPlayer(){player=new THREE.Group();playerModel=makeCat({fur:0xc98d58,cream:0xf0dfbb});player.add(playerModel);scene.add(player);player.position.set(0,0,3.8);}
function clearWorld(){while(world.children.length){let c=world.children.pop();c.traverse?.(o=>{if(o.geometry)o.geometry.dispose();if(o.material&&!Array.isArray(o.material))o.material.dispose();});}activeCats=[];}
function groundMaterial(index){let c=clans[index];return mat(c.ground);}
function buildTerritory(index){active=index;clearWorld();let c=clans[index];scene.background.setHex(c.sky);scene.fog.color.setHex(c.sky);const ground=mesh(new THREE.PlaneGeometry(125,125,40,40),groundMaterial(index),world,0,-.18,0);ground.rotation.x=-Math.PI/2;let pos=ground.geometry.attributes.position;for(let i=0;i<pos.count;i++){let x=pos.getX(i),z=pos.getY(i);pos.setZ(i,Math.sin(x*.16+index)*.16+Math.cos(z*.13)*.13+Math.sin((x+z)*.07)*.12);}ground.geometry.computeVertexNormals();
  // central camp clearing and soft trail
  let clearing=mesh(new THREE.CircleGeometry(7.7,48),mat(index===3?0xb7ad7d:index===2?0x9ca781:0x9aa77e),world,0,-.09,0);clearing.rotation.x=-Math.PI/2;let trailMat=mat(index===3?0xc1b17a:0xb8aa81);let path=mesh(new THREE.PlaneGeometry(4,26),trailMat,world,0,-.075,14);path.rotation.x=-Math.PI/2;path.rotation.z=.12;
  // camps: dens around a protected open center
